#ifndef WEB_PAGE_H
#define WEB_PAGE_H
static const char WEB_PAGE[] = "<!doctype html><html><head><meta name='viewport' content='width=device-width,initial-scale=1'><title>ESP32-C3 RGB LED Controller</title><style>body{font-family:system-ui;background:#101827;color:#fff;max-width:620px;margin:auto;padding:24px}button{padding:12px;margin:4px;border:0;border-radius:8px;font-weight:700}h1{font-size:1.6rem}.card{background:#1d293b;padding:18px;border-radius:16px;margin:14px 0}.status{font-size:1.1rem;line-height:1.8}.on{background:#22c55e}.off{background:#ef4444;color:#fff}.preset{background:#334155;color:#fff}input{width:100%;height:48px}</style></head><body><h1>ESP32-C3 RGB LED Controller</h1><div class='card'><button class='on' onclick=cmd('/api/led/on')>ON</button><button class='off' onclick=cmd('/api/led/off')>OFF</button></div><div class='card'><h3>Preset Colours</h3><div id=p></div><h3>Custom Colour</h3><input id=c type=color value='#0000ff' onchange=custom()></div><div class='card status'><b>LED STATUS</b><br>State: <span id=on>--</span><br>Color: <span id=color>--</span><br>RGB: <span id=rgb>--</span></div><script>const colors=['RED','GREEN','BLUE','YELLOW','CYAN','MAGENTA','WHITE'];p.innerHTML=colors.map(x=>`<button class=preset onclick=cmd('/api/led/color?name='+x)>${x}</button>`).join('');async function cmd(u){await fetch(u);status()}async function custom(){let h=c.value;let n=parseInt(h.slice(1),16);await cmd(`/api/led/color?r=${n>>16}&g=${n>>8&255}&b=${n&255}`)}async function status(){let x=await fetch('/api/status').then(r=>r.json());on.textContent=x.on?'ON':'OFF';color.textContent=x.color;rgb.textContent=`${x.r}, ${x.g}, ${x.b}`}status();setInterval(status,2000)</script></body></html>";
#endif
